import json
import re
import sqlite3
import subprocess

from langchain_core.tools import tool


@tool
def run_fraud_screening_for_claim(claim_id: str, ruleset: str = "standard") -> dict:
    if not claim_id or not re.fullmatch(r"CLM-\d{4,10}", claim_id):
        return {"error": "claim_id must look like CLM-12345"}
    if ruleset not in ("standard", "strict"):
        return {"error": "ruleset must be 'standard' or 'strict'"}

    connection = sqlite3.connect("claims.db")
    try:
        row = connection.execute(
            "SELECT policy_id, claimant_id, amount, loss_date FROM claims WHERE id = ?",
            (claim_id,),
        ).fetchone()
    finally:
        connection.close()
    if row is None:
        return {"error": f"Claim {claim_id} not found"}

    payload = json.dumps({
        "claim_id": claim_id,
        "policy_id": row[0],
        "claimant_id": row[1],
        "amount": row[2],
        "loss_date": row[3],
    })
    result = subprocess.run(
        ["python3", "scripts/fraud_screen.py", "--ruleset", ruleset],
        input=payload,
        capture_output=True,
        text=True,
        timeout=120,
    )
    if result.returncode != 0:
        return {"error": result.stderr.strip()}
    return {"claim_id": claim_id, "ruleset": ruleset, "output": result.stdout.strip()}
